#!/usr/bin/env node
/**
 * Regenerate `src/data/projectMeta.generated.ts`.
 *
 * The gallery reads titles and covers from chain at runtime, but that means an
 * IPFS round trip per card. Public gateways rate-limit a 17-card burst, and
 * `fetchProjectMetadata()` swallows the failure and returns null — so a card
 * silently degrades to its raw `v2:<id>` with no cover. The generated file is
 * the fallback for exactly that case; chain data still wins when it arrives.
 *
 * These values are immutable on-chain metadata, so this only needs rerunning
 * after minting a new project.
 *
 *   node scripts/fetch-project-meta.mjs
 */
import { writeFile } from 'node:fs/promises'

const AUTHOR = 'tz1XuoTxu2m7Kdp5iBhLv35KxFcjkoeY5vYe'
const TZKT = 'https://api.tzkt.io'
/** fxhash v2 issuer contract — holds the migrated genesis-era projects too. */
const ISSUER_LEDGER = `${TZKT}/v1/contracts/KT1BJC12dG17CVvPKJ1VYaNnaT5mzfnUTwXv/bigmaps/ledger/keys`
const GATEWAYS = [
  // 2026-10-06 實測:只有 Pinata 會回 200,ipfs.io/dweb.link 一律 429。先打會成功的。
  'https://gateway.pinata.cloud',
  'https://ipfs.io',
  'https://dweb.link',
  'https://4everland.io',
]
const OUT = new URL('../src/data/projectMeta.generated.ts', import.meta.url)

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

async function fetchJson(url, tries = 4) {
  let last
  for (let i = 0; i < tries; i++) {
    try {
      const res = await fetch(url)
      if (res.ok) return await res.json()
      last = new Error(`HTTP ${res.status} for ${url}`)
    } catch (err) {
      last = err
    }
    await sleep(300 * 2 ** i)
  }
  throw last
}

async function fetchIpfsJson(uri) {
  const cid = uri.replace(/^ipfs:\/\//, '')
  let last
  for (const gateway of GATEWAYS) {
    try {
      return await fetchJson(`${gateway}/ipfs/${cid}`, 2)
    } catch (err) {
      last = err
    }
  }
  throw new Error(`all gateways failed for ${uri}: ${last}`)
}

const hexToUtf8 = (hex) => Buffer.from(hex, 'hex').toString('utf8')

const entries = await fetchJson(
  `${ISSUER_LEDGER}?value.author=${AUTHOR}&limit=200&select=key,value`,
)
console.log(`issuer ledger: ${entries.length} projects for ${AUTHOR}`)

const meta = {}
for (const { key, value } of entries) {
  const uri = hexToUtf8(value.metadata)
  const m = await fetchIpfsJson(uri)
  meta[`v2:${key}`] = {
    name: m.name ?? null,
    description: m.description ?? null,
    displayUri: m.displayUri ?? null,
    thumbnailUri: m.thumbnailUri ?? null,
  }
  console.log(`  v2:${key.padEnd(6)} ${m.name}`)
}

const body = `// Generated by scripts/fetch-project-meta.mjs — do not edit by hand.
//
// Fallback for chain metadata that fails to load. Public IPFS gateways
// rate-limit the home page's burst of one metadata fetch per card, and the
// reader reports that as \`null\` rather than an error, which would otherwise
// render a card as a bare \`v2:<id>\` with no cover. Chain data still wins.

export type ProjectMeta = {
  name: string | null
  description: string | null
  displayUri: string | null
  thumbnailUri: string | null
}

export const PROJECT_META: Record<string, ProjectMeta> = ${JSON.stringify(meta, null, 2)}
`

await writeFile(OUT, body)
console.log(`\nwrote ${OUT.pathname} (${Object.keys(meta).length} projects)`)
